namespace Kaff.Api.Features.DailyLogs.RecordDayLabour;

/// <summary>Hours a day labourer worked. There is no rate member: the rate is not the engineer's.</summary>
/// <param name="EntryId">Generated by the device, so a retried sync is recognised and not counted twice.</param>
/// <param name="OccurredAt">When it happened on site, with the device's offset. Decides which day the entry belongs to.</param>
public sealed record Request(Guid? EntryId, DateTimeOffset? OccurredAt, Guid? EmployeeId, decimal Hours);
